from pathlib import Path
import shutil,re
root=Path(__file__).resolve().parents[1]
dest=root/'portfolio/main/static/main/phosphene';dest.mkdir(exist_ok=True)
for old in dest.glob('index-*'):
    old.unlink()
for f in (root/'phosphene/dist/assets').iterdir(): shutil.copy(f,dest/f.name)
shutil.copy(root/'phosphene/public/dot.svg',dest/'dot.svg')
shutil.copytree(root/'phosphene/public/certificates',dest/'certificates',dirs_exist_ok=True)
s=(root/'phosphene/dist/index.html').read_text()
s=re.sub(r'"/assets/([^"]+)"',lambda m:'"{% static \'main/phosphene/'+m[1]+'\' %}"',s)
s=s.replace('href="/dot.svg"','href="{% static \'main/phosphene/dot.svg\' %}"')
s=s.replace('<main id="app"></main>', '''{{ portfolio_content|json_script:"portfolio-content" }}<main id="app"><section class="hero" id="top"><div class="ego-switch mono" role="group" aria-label="Choose your alter ego"><span>Alter ego</span><a href="?as=researcher" {% if portfolio_content.ego == "research" %}aria-current="true"{% endif %}>Research</a><a href="?as=engineer" {% if portfolio_content.ego == "engineering" %}aria-current="true"{% endif %}>Engineering</a></div><h1>{{ portfolio_content.name }}</h1><p class="fallback-researcher">{{ portfolio_content.personas.researcher.tagline }}</p><p class="fallback-engineer">{{ portfolio_content.personas.engineer.tagline }}</p></section><section id="about"><h2>About</h2><p class="fallback-researcher">{{ portfolio_content.personas.researcher.about }}</p><p class="fallback-engineer">{{ portfolio_content.personas.engineer.about }}</p></section><section id="research"><h2>Research</h2>{% for r in portfolio_content.research %}<article><h3>{{ r.title }}</h3><p>{{ r.summary }}</p><span>{{ r.status }}</span>{% if r.link %}<a href="{{ r.link }}">Read research</a>{% endif %}</article>{% endfor %}</section><section id="projects"><h2>Projects</h2>{% for p in portfolio_content.projects %}<article><h3>{{ p.title }}</h3><p>{{ p.summary }}</p></article>{% endfor %}</section><section id="achievements"><h2>Achievements</h2>{% for a in portfolio_content.achievements %}<article><h3>{{ a.title }}</h3><p>{{ a.summary }}</p>{% if a.image %}<a href="{{ a.image }}">View record</a>{% endif %}</article>{% empty %}<p>Selected achievements will appear here.</p>{% endfor %}</section><section id="certificates"><h2>Certificates</h2><div class="certificate-grid">{% for a in portfolio_content.certificates %}<article class="certificate-item"><h3>{{ a.title }}</h3><p>{{ a.category }} / {{ a.date }}</p>{% if a.image %}<a class="certificate-image" href="{{ a.image }}"><img src="{{ a.image }}" alt="{{ a.title }}" loading="lazy"></a>{% endif %}</article>{% endfor %}</div></section><section><h2>Experience and education</h2>{% for r in portfolio_content.credentials %}<article><h3>{{ r.role }}</h3><p>{{ r.institution }} / {{ r.dates }}</p><p>{{ r.description }}</p></article>{% endfor %}</section><section id="contact"><h2>Contact</h2>{% if portfolio_content.email %}<a class="email" href="mailto:{{ portfolio_content.email }}">{{ portfolio_content.email }}</a>{% endif %}{% for s in portfolio_content.socials %}{% if s.url %}<p><a href="{{ s.url }}">{{ s.label }}</a></p>{% endif %}{% endfor %}</section></main>''')
(root/'portfolio/main/templates/main/phosphene.html').write_text('{% load static %}\n'+s)
